using GraphApi.Models.ARC.TiposArchivo;namespace GraphApi.Services.ARC.TiposArchivo{    /// <summary>    /// Define las operaciones de negocio y persistencia para TiposArchivos.    /// </summary>    public interface ITiposArchivoService    {        /// <summary>        /// Obtiene la lista de TiposArchivos con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTiposArchivo>> GetTiposArchivos(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de TiposArchivos con filtros opcionales.        /// </summary>        /// <param name="tipoArchivoID">Filtro opcional para TipoArchivoID.</param>        /// <param name="tipoArchivo">Filtro opcional para TipoArchivo.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTiposArchivosDynamic(            int? tipoArchivoID,            string? tipoArchivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo TiposArchivo.        /// </summary>        /// <param name="objInput">Datos para crear el TiposArchivo.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposArchivo> CreateTiposArchivo(            clCreateTiposArchivo objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un TiposArchivo.        /// </summary>        /// <param name="objInput">Datos para actualizar el TiposArchivo, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposArchivo?> UpdateTiposArchivo(            clUpdateTiposArchivo objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un TiposArchivo por su ID.        /// </summary>        /// <param name="nTiposArchivoID">ID del TiposArchivo a eliminar.</param>        Task<bool> DeleteTiposArchivo(int nTiposArchivoID);    }}